64:    const sortChannels = (channels: GroupChannel[], pinnedChannelsToSort: string[]) => {
65:        const pinnedChans = channels.filter(ch => pinnedChannelsToSort.includes(ch.url));
66:        const unpinnedChans = channels.filter(ch => !pinnedChannelsToSort.includes(ch.url));
67:
68:        const sortedPinned = [...pinnedChans].sort((a, b) => {
69:            const aIndex = pinnedChannelsToSort.indexOf(a.url);
70:            const bIndex = pinnedChannelsToSort.indexOf(b.url);
71:            return aIndex - bIndex;
72:        });
73:
74:        const sortedUnpinned = [...unpinnedChans].sort((a, b) => {
75:            const aTime = a.lastMessage?.createdAt || 0;
