91:            }
92:
93:            setIsInitialized(true);
94:        }
95:    }, [profileSettings?.pinnedChannels, sb.groupChannel]);
96:
97:    // Handle pinned channels changes
98:    useEffect(() => {
99:        // We check if initialized since we're getting pinned from our backend, and all the channels from sendbird, just want to reduce any race conditions
100:        // This also fires when we pin or unpin after load.
101:        if (isInitialized) {
102:            // Rearrange the current channel list to respect new pinned order
103:            setChannelList(prevChannels => {
104:                const sortedChannels = sortChannels(prevChannels, pinnedChannels);
105:                return sortedChannels;
106:            });
107:        }
108:    }, [pinnedChannels, isInitialized]);
109:
110:    // This gets the top X channels and updates the list, this is mainly used for user activity
111:    // This is called on a timer, this is in order to update user status, etc.
112:    const refreshRecentChannels = useCallback(async () => {
113:        // If we're searching, don't refresh since it would override the search.
114:        if (!sb.groupChannel || debouncedSearchTerm !== '') {
115:            return;
116:        }
117:
118:        try {
119:            const query = sb.groupChannel.createMyGroupChannelListQuery({
120:                limit: TOP_CHANNELS_LIMIT,
121:                includeEmpty: false,
122:                order: GroupChannelListOrder.LATEST_LAST_MESSAGE
123:            });
124:
125:            const recentChannels = await query.next();
126:
127:            // Update existing channels preserving pinned order
128:            setChannelList(prevChannels => {
129:                const recentChannelMap = new Map(recentChannels.map(ch => [ch.url, ch]));
130:
131:                // First, update all existing channels with new data
132:                const updatedChannels = prevChannels.map(channel =>
133:                    recentChannelMap.get(channel.url) || channel
134:                );
135:
136:                // Add any new channels that weren't in our list
137:                recentChannels.forEach(channel => {
138:                    if (!updatedChannels.some(ch => ch.url === channel.url)) {
139:                        updatedChannels.push(channel);
140:                    }
141:                });
142:
143:                return sortChannels(updatedChannels, pinnedChannels);
144:            });
145:        } catch (error) {
146:            log.error('Error refreshing recent channels', error);
147:        }
148:    }, [sb.groupChannel, pinnedChannels, debouncedSearchTerm]);
149:
150:    // This gets all the channels from sendbird, this is used for the initial load and the search.
151:    const getChannels = async (searchKeyword = '') => {
152:        if (!sb.groupChannel) {
153:            return [];
154:        }
155:
156:        try {
157:            const query = sb.groupChannel.createMyGroupChannelListQuery({
158:                limit: 100, // 100 is the max limit for sendbird
159:                includeEmpty: true,
160:                order: GroupChannelListOrder.LATEST_LAST_MESSAGE,
161:                ...(searchKeyword && {
162:                    searchFilter: {
163:                        query: searchKeyword,
164:                        fields: [GroupChannelSearchField.CHANNEL_NAME, GroupChannelSearchField.MEMBER_NICKNAME],
165:                    }
166:                })
167:            });
168:
169:            // Get all channels in one go
170:            const channels: GroupChannel[] = [];
171:            while (query.hasNext) {
172:                // eslint-disable-next-line no-await-in-loop
173:                const batch = await query.next();
174:                channels.push(...batch);
175:            }
176:
177:            return channels;
178:        } catch (error) {
179:            log.error('Error fetching channels', error);
