198:        const firstChannel = mainChannelList[0]
199:            ?? (!isCustomerSuccessStaff ? channelList.find(ch => isCustomerSuccessChannel(ch)) : undefined);
200:        if (firstChannel) {
201:            setLocation(`/${calledChatRoutes.chat.route}/${firstChannel.url}`);
202:        }
203:    };
204:
205:    async function fetchInitialData() {
206:        if (!isInitialized || !sb.groupChannel) {
207:            return;
208:        }
209:
210:        setListLoading(true);
211:        try {
212:            const allChannels = await getChannels();
213:            const sortedChannels = sortChannels(allChannels, pinnedChannels);
214:            setChannelList(sortedChannels);
215:        } catch (error) {
216:            log.error('Error fetching initial channels', error);
217:        } finally {
218:            setListLoading(false);
219:        }
220:         
221:    }
222:
223:    const refreshSendbird = useSendbirdConnectionStore((state) => state.refreshSendbird);
224:
225:    usePullToRefreshAddHandler(refreshSendbird);
226:
227:    // When there's no channelUrl, land on the first channel. Keyed on channelUrl
