237:
238:    // Fetch once initialized
239:    useEffect(() => {
240:        if (isInitialized) {
241:            void fetchInitialData();
242:        }
243:    }, [isInitialized]);
244:
245:    const removeChannelFromPinned = useCallback((channelToRemove: string) => {
246:        // Remove from local state
