251:            body: {
252:                pinnedChannels: profileSettings?.pinnedChannels?.filter(
253:                    pinnedChannel => pinnedChannel.channel !== channelToRemove
254:                ) || [],
255:            },
256:        });
257:    }, [profileSettings?.pinnedChannels, patchSettings]);
258:
259:    useEffect(() => {
260:        if (!sb.groupChannel) {
261:            return () => {};
262:        }
263:
264:        // Setup channel handler for real-time updates, this is called from the handlers below.
265:        const updateChannelList = (baseChannel: BaseChannel) => {
266:            const channel = baseChannel as GroupChannel;
267:            setChannelList(prevChannels => {
268:                // First update/add the changed channel
269:                const updatedChannels = prevChannels.map(ch =>
270:                    ch.url === channel.url ? channel : ch
