282:        const channelHandler = new GroupChannelHandler({
283:            onMessageReceived: (channel) => {
284:                updateChannelList(channel);
285:            },
286:            onMessageUpdated: (channel) => {
287:                updateChannelList(channel);
288:            },
289:            onUnreadMemberStatusUpdated: (channel) => {
290:                updateChannelList(channel);
291:            },
292:            onChannelChanged: (channel) => {
293:                updateChannelList(channel);
294:            },
295:            onChannelDeleted: (deletedChannelUrl) => {
296:                // Remove from channel list
297:                setChannelList(prevChannels =>
298:                    prevChannels.filter(ch => ch.url !== deletedChannelUrl)
299:                );
300:
301:                if (pinnedChannels.includes(deletedChannelUrl)) {
302:                    removeChannelFromPinned(deletedChannelUrl);
303:                }
304:
305:                void refreshRecentChannels();
306:            },
307:            onUserJoined: (baseChannel, user) => {
308:                const channel = baseChannel as GroupChannel;
309:                if (user.userId === sb.currentUser?.userId) {
310:                    setChannelList(prevChannels => {
311:                        // Check if this channel already existed in our list
312:                        const joinChannelExists = prevChannels.some(ch => ch.url === channel.url);
313:
314:                        if (!joinChannelExists) {
315:                            // Only reorder for new channels
316:                            const lastPinnedIndex = pinnedChannels.length > 0
317:                                ? prevChannels.findIndex(ch => ch.url === pinnedChannels[pinnedChannels.length - 1])
318:                                : -1;
319:
320:                            return [
321:                                ...prevChannels.slice(0, lastPinnedIndex + 1),
322:                                channel,
323:                                ...prevChannels.slice(lastPinnedIndex + 1)
324:                            ];
325:                        }
326:
327:                        // For existing channels, just update the channel data in place
328:                        return prevChannels.map(ch =>
329:                            ch.url === channel.url ? channel : ch
330:                        );
331:                    });
332:                }
333:                // refresh the recent channels
334:                void refreshRecentChannels();
335:            },
336:            onUserLeft: (baseChannel, user) => {
337:                const channel = baseChannel as GroupChannel;
338:
339:                // onUserLeft fires for EVERY remaining member when anyone leaves, so
