375:            return undefined;
376:        }
377:
378:        if (channelList.some(channel => channel.url === channelUrl)) {
379:            return undefined;
380:        }
381:
382:        let cancelled = false;
383:
384:        void (async () => {
385:            try {
386:                const channel = await sb.groupChannel.getChannel(channelUrl);
387:                if (cancelled || !channel || channel.url !== channelUrl) {
