415:    // Remember the last channel the user actually landed on so the "Chat" nav
416:    // button can bring them back here. We only persist a channel that's in the
417:    // list, which guarantees it's real and viewable (DMs included) and excludes
418:    // placeholders like 'undefined'/'new' or channels the user has left. Read
419:    // via getState() so writing doesn't re-render this list on every refresh.
420:    useEffect(() => {
421:        if (!channelUrl || !channelList.some(channel => channel.url === channelUrl)) {
