473:    const filteredChannelList = useMemo(
474:        () => (activeFilter === 'customer_support'
475:            ? filterChannels(channelList, 'customer_support')
476:            : filterChannels(mainChannelList, activeFilter)),
477:        [channelList, mainChannelList, activeFilter]
478:    );
