480:    const setSharedChannelList = useChannelListStore((state) => state.setChannelList);
481:    useEffect(() => {
482:        setSharedChannelList(channelList);
483:    }, [channelList, setSharedChannelList]);
484:
485:    const currentUserId = sb.currentUser?.userId ?? '';
486:    const searchFilteredChannels = useMemo(() => {
487:        if (!searchTerm) {
488:            return filteredChannelList;
489:        }
